	@Test
	void deadlineCancellationReleasesEveryAsyncVariant() throws Exception {
		List<Function<CloseableIteration<BindingSet>, CloseableIteration<BindingSet>>> factories = List.of(
				AsyncIteratorBuffer::new, AsyncIteratorDirect::new, AsyncIteratorReadAhead::new);
		for (var factory : factories) {
			CloseOnlyIteration source = new CloseOnlyIteration();
			IllegalStateException timeout = new IllegalStateException("test deadline expired");
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(500);
					ExecutorService caller = Executors.newSingleThreadExecutor();
					TimeLimitIteration<BindingSet> timed = new TimeLimitIteration<>(factory.apply(source), deadline) {
						{
							registerDeadline();
						}

						@Override
						protected void throwInterruptedException() {
							throw timeout;
						}
					}) {
				try {
					assertTrue(timed.hasNext());
					timed.next();
					assertTrue(source.waiting.await(5, TimeUnit.SECONDS));
					Future<Boolean> waiting = caller.submit(timed::hasNext);
					ExecutionException failure = assertThrows(ExecutionException.class,
							() -> waiting.get(5, TimeUnit.SECONDS));
					assertSame(timeout, failure.getCause());
					assertTrue(source.returned.await(2, TimeUnit.SECONDS), "timeout must release the worker's source");
					timed.close();
					assertEquals(1, source.closeCalls.get());
				} finally {
					source.released.countDown();
				}
			}
		}
	}

	@Test
	void sourceCloseFailureStillWaitsForAdmittedCleanup() throws Exception {
		AsyncIteratorWorker worker = new AsyncIteratorWorker();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch released = new CountDownLatch(1);
		CountDownLatch cleanupEntered = new CountDownLatch(1);
		CountDownLatch cleanupReleased = new CountDownLatch(1);
		IllegalStateException failure = new IllegalStateException("source close failed");
		AtomicBoolean interrupted = new AtomicBoolean();
		try (ExecutorService executor = Executors.newSingleThreadExecutor();
				ExecutorService closer = Executors.newSingleThreadExecutor()) {
			worker.submit(executor, () -> {
				entered.countDown();
				awaitUninterruptibly(released);
				try {
					return null;
				} finally {
					cleanupEntered.countDown();
					awaitUninterruptibly(cleanupReleased);
				}
			});
			assertTrue(entered.await(5, TimeUnit.SECONDS));
			Future<?> close = closer.submit(() -> {
				Thread.currentThread().interrupt();
				try {
					worker.cancelAndClose(() -> {
						assertFalse(Thread.currentThread().isInterrupted(), "cleanup must be allowed to acquire locks");
						released.countDown();
						throw failure;
					});
				} finally {
					interrupted.set(Thread.currentThread().isInterrupted());
				}
			});
			try {
				assertTrue(cleanupEntered.await(5, TimeUnit.SECONDS));
				assertThrows(TimeoutException.class, () -> close.get(250, TimeUnit.MILLISECONDS),
						"even a failing source close must wait for the worker's cleanup");
			} finally {
				released.countDown();
				cleanupReleased.countDown();
			}
			assertSame(failure,
					assertThrows(ExecutionException.class, () -> close.get(5, TimeUnit.SECONDS)).getCause());
			assertTrue(interrupted.get());
		}
	}

