	private static void assertPromptSourceClose(
			Function<CloseableIteration<BindingSet>, CloseableIteration<BindingSet>> factory) throws Exception {
		CloseOnlyIteration source = new CloseOnlyIteration();
		CloseableIteration<BindingSet> iteration = factory.apply(source);
		ExecutorService closer = Executors.newSingleThreadExecutor();
		try {
			assertTrue(iteration.hasNext());
			iteration.next();
			assertTrue(source.waiting.await(5, TimeUnit.SECONDS), "worker must enter its source wait");
			Future<Boolean> closed = closer.submit(() -> {
				Thread.currentThread().interrupt();
				iteration.close();
				return Thread.currentThread().isInterrupted();
			});
			assertTrue(source.released.await(2, TimeUnit.SECONDS),
					"close must release an interrupt-insensitive source promptly");
			assertTrue(closed.get(5, TimeUnit.SECONDS), "source cancellation must preserve the closer's interrupt");
			assertEquals(0, source.returned.getCount(), "close must await the released worker");
			assertEquals(1, source.closeCalls.get());
		} finally {
			source.released.countDown();
			closer.shutdown();
			assertTrue(closer.awaitTermination(5, TimeUnit.SECONDS));
			iteration.close();
		}
	}

	private static final class CloseOnlyIteration implements CloseableIteration<BindingSet> {
		private final CountDownLatch waiting = new CountDownLatch(1);
		private final CountDownLatch released = new CountDownLatch(1);
		private final CountDownLatch returned = new CountDownLatch(1);
		private final AtomicInteger closeCalls = new AtomicInteger();
		private boolean first = true;

		@Override
		public boolean hasNext() {
			if (first) {
				return true;
			}
			waiting.countDown();
			awaitUninterruptibly(released);
			returned.countDown();
			return false;
		}

		@Override
		public BindingSet next() {
			first = false;
			return new MapBindingSet();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCalls.incrementAndGet();
			released.countDown();
		}
	}

